cat app/src/main/java/com/example/features/offlinecache/LocalAudioScreen.kt | \
sed -e 's/import androidx.compose.material.icons.filled.Storage/import androidx.compose.material.icons.filled.Storage\nimport androidx.compose.material.icons.filled.FolderOpen/g' \
    -e 's/val launcher = rememberLauncherForActivityResult(/val folderLauncher = rememberLauncherForActivityResult(ActivityResultContracts.OpenDocumentTree()) { uri ->\n        if (uri != null) {\n            context.contentResolver.takePersistableUriPermission(uri, android.content.Intent.FLAG_GRANT_READ_URI_PERMISSION)\n            coroutineScope.launch {\n                isScanning = true\n                try {\n                    repository.syncLocalFolder(context, uri)\n                    Toast.makeText(context, "Klasör başarıyla tarandı", Toast.LENGTH_SHORT).show()\n                } catch (e: Exception) {\n                    Toast.makeText(context, "Klasör tarama hatası: ${e.localizedMessage}", Toast.LENGTH_SHORT).show()\n                } finally {\n                    isScanning = false\n                }\n            }\n        }\n    }\n\n    val launcher = rememberLauncherForActivityResult(/g' \
    -e 's/Text("Toplam İndekslenen: ${localSongs.size} parça", color = YouTubeRed, fontSize = 12.sp, fontWeight = FontWeight.Bold)/Text("Toplam İndekslenen: ${localSongs.size} parça", color = YouTubeRed, fontSize = 12.sp, fontWeight = FontWeight.Bold)\n                Spacer(modifier = Modifier.height(12.dp))\n                Button(\n                    onClick = { folderLauncher.launch(null) },\n                    colors = ButtonDefaults.buttonColors(containerColor = SurfaceVariantColor),\n                    shape = RoundedCornerShape(8.dp),\n                    modifier = Modifier.fillMaxWidth()\n                ) {\n                    Icon(Icons.Default.FolderOpen, contentDescription = null, tint = TextPrimary, modifier = Modifier.size(18.dp))\n                    Spacer(modifier = Modifier.width(8.dp))\n                    Text("Özel Klasör Seç (SAF)", color = TextPrimary, fontSize = 13.sp)\n                }/g' \
> new_LocalAudioScreen.kt
mv new_LocalAudioScreen.kt app/src/main/java/com/example/features/offlinecache/LocalAudioScreen.kt
